<?php
declare(strict_types=1);
return static function(PDO $c):string{$steps=array_map('intval',$c->query("SELECT statement_number FROM schema_migration_steps WHERE version='060' ORDER BY statement_number")->fetchAll(PDO::FETCH_COLUMN));if($steps!==[]&&$steps!==range(1,max($steps)))throw new RuntimeException('Migration 060 recovery steps are not a valid completed prefix.');$table=(int)$c->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='operations_task_runs'")->fetchColumn();$permissions=(int)$c->query("SELECT COUNT(*) FROM permissions WHERE code IN('administration.integration_events.view','administration.integration_events.retry') AND active=TRUE")->fetchColumn();$complete=$table===1&&$permissions===2;if($steps!==[]&&max($steps)>=2&&!$complete)throw new RuntimeException('Migration 060 recovery metadata does not match the database state.');return$steps===[]&&$complete?'baseline':'apply';};
